head.script:
scwin.onpageload = function () {
    // 달력 아이콘 클릭으로 팝업 달력이 열리면 겹침 여부 출력
    document.addEventListener("click", scwin.onDocumentClick, true);
};

// 화면에 보이는 요소인지 확인
scwin.isVisible = function (elem) {
    return !!elem && elem.offsetWidth > 0 && elem.offsetHeight > 0 && getComputedStyle(elem).visibility !== "hidden";
};

// 달력 아이콘 클릭 시 팝업이 열린 뒤 겹침 확인
scwin.onDocumentClick = function (e) {
    let icon = e.target && e.target.closest ? e.target.closest("[id$='_img'], button.w2inputCalendar_button") : null;
    if (icon && icon.id.indexOf(grd_target.id) >= 0) {
        setTimeout(scwin.printOverlap, 300);
    }
};

// 열린 팝업 달력 위쪽의 연도/월 SelectBox 와 이전/다음 버튼이 겹치는지 출력
scwin.printOverlap = function () {
    let cals = document.querySelectorAll("div.w2calendar[id*='" + grd_target.id + "']");
    let cal = null;
    for (let i = 0; i < cals.length; i++) {
        if (scwin.isVisible(cals[i])) {
            cal = cals[i];
        }
    }
    if (!cal) {
        return;
    }
    let col = cal.id.indexOf("dateA") >= 0 ? "dateA (true)" : "dateB (false)";
    let sels = [];
    [["year", "연도"], ["month", "월"]].forEach(function (info) {
        let sel = cal.querySelector("[class*='w2calendar_selectbox_" + info[0] + "']");
        if (scwin.isVisible(sel)) {
            sels.push({ "name" : info[1] + " SelectBox", "rect" : sel.getBoundingClientRect() });
        }
    });
    let btns = [["last_year", "이전 연도"], ["last_month", "이전 월"], ["next_month", "다음 월"], ["next_year", "다음 연도"]];
    let hits = [];
    btns.forEach(function (info) {
        let b = cal.querySelector(".w2calendar_header_" + info[0]);
        if (!scwin.isVisible(b)) {
            return;
        }
        let r = b.getBoundingClientRect();
        sels.forEach(function (s) {
            if (r.left < s.rect.right && s.rect.left < r.right && r.top < s.rect.bottom && s.rect.top < r.bottom) {
                hits.push(info[1] + " 버튼 ↔ " + s.name);
            }
        });
    });
    scwin.setReturnValue("[" + col + "] " + (hits.length ? "겹침 : " + hits.join(", ") + " → FAIL" : "겹침 없음 → PASS"));
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
